'use strict';
const $=id=>document.getElementById(id);
let project=null,projectId='',selected=null,episode='',mode='outline',socket=null,work=[],treeOpen=new Set(),drafts={},renderKey='',timer,reconnectTimer;
let openedEpisodes=[];
let storyAssetsReady=false,writtenImportReady=false;
const contextDrafts={};
function contextDraftKey(){return projectId+':'+(selected||'story')}
let episodeZoom=1;
let assembledEpisodePreview=null;
const shotKinds=['keyframe','clip','reference'];
function node(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function toast(message){$('toast').textContent=message;$('toast').classList.remove('hidden');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.add('hidden'),6500)}
async function api(url,method='GET',body){const r=await fetch(url,{method,headers:body instanceof FormData?{}:{'Content-Type':'application/json'},body:body?(body instanceof FormData?body:JSON.stringify(body)):undefined});let value;try{value=await r.json()}catch{throw Error('Server response could not be read')}if(!r.ok)throw Error(r.status===404&&url.includes('/story-assets')?'Restart J Director after the current render to activate the story-asset update. No story files were changed.':value.detail||'Request failed');return value}
async function safe(fn){try{return await fn()}catch(e){toast(e.message);console.error(e)}}
function base(){return '/api/projects/'+projectId}
function values(){return project?Object.values(project.nodes):[]}
function children(parent){return values().filter(n=>n.parent===parent).sort((a,b)=>a.order-b.order)}
function episodeNodes(){return children(null).flatMap(n=>n.kind==='episode'?[n]:n.kind==='arc'?children(n.id).filter(x=>x.kind==='episode'):[])}
function episodeOf(n){while(n){if(n.kind==='episode')return n.id;n=project.nodes[n.parent]}return null}
function media(path){return base()+'/asset?path='+encodeURIComponent(path)}
function current(){return selected?project?.nodes[selected]:null}
function isEditable(n){return n&&!n.locked&&!['running','queued','succeeded'].includes(n.status)}
function remember(nid,field,value){drafts[nid]??={};drafts[nid][field]=value}
function fieldValue(n,field){return drafts[n.id]?.[field]??n[field]??''}
async function commit(nid=selected){if(nid&&drafts[nid]){const changes=drafts[nid];const state=await api(base()+'/nodes/'+nid,'PATCH',changes);delete drafts[nid];accept(state)}return true}
async function listProjects(){const data=await api('/api/projects');$('projectPicker').replaceChildren(new Option('Choose a project',''),...data.map(p=>new Option(p.title,p.id)));$('projectPicker').value=projectId;return data}
async function openProject(id){assembledEpisodePreview=null;clearTimeout(reconnectTimer);if(socket){socket.onclose=null;socket.close()}projectId=id;selected=null;episode='';openedEpisodes=[];mode='outline';drafts={};renderKey='';if(!id){project=null;updateModeChrome();return}localStorage.setItem('director-project',id);const r=await api(base());project=r.project;work=r.jobs;episode=values().find(n=>n.kind==='episode')?.id||'';$('welcome').classList.add('hidden');$('workspace').classList.remove('hidden');await listProjects();render();connect()}
function accept(s,jobs){if(!s||s.id!==projectId)return;if(project&&s.revision<project.revision)return;project=s;if(jobs)work=jobs;render()}
function connect(){if(!projectId)return;const connectedProject=projectId;socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/ws/'+projectId);socket.onopen=()=>{$('connection').textContent='● Live updates'};socket.onmessage=e=>{const d=JSON.parse(e.data);if(d.type==='project_deleted'&&projectId===connectedProject)safe(async()=>{localStorage.removeItem('director-project');await openProject('');await listProjects();toast('This project was deleted. Its characters/backgrounds were preserved in the catalogue.')});else if(d.type==='state')accept(d.project,d.jobs)};socket.onclose=()=>{ $('connection').textContent='Reconnecting…';if(projectId)reconnectTimer=setTimeout(()=>{if(socket?.readyState===WebSocket.CLOSED)connect()},2500)}}
async function reload(){const r=await api(base());accept(r.project,r.jobs)}
async function choose(id){if(project?.nodes[id]?.kind==='episode')return openEpisode(id);assembledEpisodePreview=null;await commit();selected=id;const n=current();if(n){const ep=episodeOf(n);if(ep){episode=ep;if(shotKinds.includes(n.kind)&&!openedEpisodes.includes(ep))openedEpisodes.push(ep)}mode=shotKinds.includes(n.kind)||n.kind==='scene'?'pipeline':'outline'}else mode='outline';renderKey='';render()}
function setMode(value){mode=value;updateModeChrome();if(isLibraryMode())safe(loadLibrary);else render()}
function renderTree(){const root=$('tree');root.replaceChildren();root.append(treeHeading('OUTLINE',()=>showOutlineDialog(),()=>safe(()=>choose(null))));
function branch(n){const container=node('div','');const kids=children(n.id);if(n.kind==='sequence'){kids.forEach(k=>container.append(branch(k)));return container}if(kids.length){const details=node('details');details.open=treeOpen.has(n.id);const summary=node('summary','tree-summary'+(selected===n.id?' selected':''),n.title);summary.onclick=e=>{e.preventDefault();if(details.open)treeOpen.delete(n.id);else treeOpen.add(n.id);safe(()=>choose(n.id))};details.append(summary);details.ontoggle=()=>details.open?treeOpen.add(n.id):treeOpen.delete(n.id);if(!['episode','scene'].includes(n.kind)){const open=node('button','tree-item'+(selected===n.id?' selected':''),'Edit '+n.kind);open.onclick=()=>safe(()=>choose(n.id));details.append(open)}const group=node('div','tree-children');kids.forEach(k=>group.append(branch(k)));details.append(group);container.append(details)}else{const button=node('button','tree-item'+(selected===n.id?' selected':''),(n.kind==='clip'?'▷ ':n.kind==='keyframe'?'▧ ':'')+n.title);button.title=n.title;button.onclick=()=>safe(()=>choose(n.id));container.append(button)}return container}
children(null).filter(n=>['arc','episode'].includes(n.kind)).forEach(n=>root.append(branch(n)));
for(const [kind,label] of [['character','STORY CHARACTERS'],['location','STORY BACKGROUNDS']]){root.append(treeHeading(label,()=>showStoryAssetDialog(kind),()=>openStoryAssetGroup(kind)));values().filter(n=>n.kind===kind&&!n.archived).forEach(n=>{const button=node('button','tree-item'+(selected===n.id?' selected':''),n.title);button.onclick=()=>safe(()=>choose(n.id));root.append(button)})}root.append(treeHeading('CATALOGUE',()=>setMode('characters'),()=>setMode('characters')))}

function render(){updateModeChrome();renderWorkControls();renderRunScope();applyPipelineCollapse();if(isLibraryMode())return;if(!project)return;$('reviewArea').classList.toggle('hidden',mode!=='outline');$('pipelineArea').classList.toggle('hidden',mode!=='pipeline');renderPreview();const editing=document.activeElement;if(editing&&['INPUT','TEXTAREA'].includes(editing.tagName)&&editing.closest('.studio-main')){if(editing.id==='contextText')renderReview();renderLogs();return}$('projectTitle').textContent=project.title;$('projectPath').textContent='PROJECT / '+project.id;$('quality').value=project.quality;$('quality').disabled=work.length>0;const episodes=episodeNodes();if(!episode&&episodes.length)episode=episodes[0].id;$('episodePicker').replaceChildren(...(episodes.length?episodes.map(n=>new Option(n.title,n.id)):[new Option('Outline not ready yet','')]));$('episodePicker').value=episode;$('outlineMode').classList.toggle('active',mode==='outline');$('pipelineMode').classList.toggle('active',mode==='pipeline');$('reviewArea').classList.toggle('hidden',mode!=='outline');$('pipelineArea').classList.toggle('hidden',mode!=='pipeline');renderTree();renderReview();renderPipeline();renderEditor();renderProduction();renderLogs()}
function renderReview(){const n=current();const context=n&&!shotKinds.includes(n.kind)?n:null;const kind=context?.kind||'story';$('reviewArea').dataset.level=kind;const target={story:'episodes',arc:'episodes',episode:'scenes',scene:'keyframes & clips',sequence:'keyframes & clips'}[kind];$('importWritten').classList.toggle('hidden',kind!=='story'||!/^\s*(?:#{1,6}\s*)?(?:\*\*)?EPISODE\s+\d+\s*[:—–-]/im.test(project.story_working));$('importWritten').disabled=!!work.length||!writtenImportReady;$('importWritten').title=writtenImportReady?'Preserve your written episode, scene and keyframe structure':'Restart J Director after active work finishes to load the written-story importer';$('reviewLevel').textContent=kind.toUpperCase();$('reviewTitle').textContent=context?.title||'Shape the story';$('contextLabel').textContent=kind==='episode'?'Write this episode in detail — dialogue, actions, pacing and ending':context?'Selected '+kind:'Working story';if(document.activeElement!==$('contextText'))$('contextText').value=contextDrafts[contextDraftKey()]??(context?fieldValue(context,'text'):project.story_working);$('reviewHelp').textContent=kind==='story'?'One click plans the story directly into editable episodes, then stops. Edit the cards and use ↑ / ↓ to reorder. Select any episode to develop its scenes, keyframes, images and videos one step at a time.':kind==='arc'?'Create episodes for this arc, then choose an episode when you are ready. No scenes or media run automatically.':'Work on this selected level only. Review and edit its results before choosing the next step, or explicitly use Run All for this episode.';$('breakdown').textContent=kind==='story'?'Break down outline: episodes + characters + backgrounds':target?'Review → generate '+target:'Select an outline level';const hasScenes=kind==='episode'&&children(context.id).some(n=>n.kind==='scene');$('redoBreakdown').classList.toggle('hidden',!hasScenes);$('redoBreakdown').disabled=!!work.length;$('breakdown').disabled=!target||work.length>0||hasScenes;$('enhanceLevel').disabled=work.length>0;$('enhanceChildren').disabled=work.length>0;const cards=$('reviewCards');cards.replaceChildren();children(context?.id||null).filter(x=>!['character','location','prop','reference','clip'].includes(x.kind)).forEach((child,i)=>{const card=node('article','review-card');card.append(node('span','number',child.kind.toUpperCase()+' / '+String(i+1).padStart(2,'0')));const title=node('input');title.value=fieldValue(child,'title');title.setAttribute('aria-label','Title');title.oninput=()=>remember(child.id,'title',title.value);const text=node('textarea');text.rows=5;text.value=fieldValue(child,'text');text.setAttribute('aria-label',child.title+' outline');text.oninput=()=>remember(child.id,'text',text.value);card.append(title,text);const tools=node('div','button-row');for(const [label,fn] of [['↑',async()=>{for(const id of Object.keys(drafts))await commit(id);await action('move',child.id,{direction:'up'})}],['↓',async()=>{for(const id of Object.keys(drafts))await commit(id);await action('move',child.id,{direction:'down'})}],['Keep edits',()=>commit(child.id)],['Open →',()=>choose(child.id)]]){const b=node('button','',label);b.onclick=()=>safe(fn);tools.append(b)}card.append(tools);cards.append(card)})}
function pipelineNodes(){return values().filter(n=>['keyframe','clip'].includes(n.kind)&&episodeOf(n)===episode)}
function renderPipeline(){const root=$('pipeline');root.replaceChildren();const nodes=pipelineNodes();if(!nodes.length){root.append(node('p','muted','Write your episode in detail, then create scenes and keyframes one step at a time.'))}const epNode=project.nodes[episode];const pilot=project.motion_comic_preview;$('showMotionPilot').classList.toggle('hidden',!pilot||pilot.episode!==episode);$('showMotionPilot').onclick=()=>safe(async()=>{await commit();selected=null;assembledEpisodePreview={id:'assembled-motion-pilot-'+episode,episode,kind:'clip',output:pilot.path,version:Math.round(pilot.created*1000),title:pilot.title};renderKey='';render()});$('editEpisodeDetails').disabled=!epNode;$('editEpisodeDetails').onclick=()=>safe(()=>openOutlineEditor(epNode.id));const scenes=[...(children(episode).some(n=>n.kind==='keyframe')?[project.nodes[episode]]:[]),...values().filter(n=>n.kind==='scene'&&episodeOf(n)===episode).sort((a,b)=>a.order-b.order)];let sceneCount=0;for(const scene of scenes){if(sceneCount++)root.append(node('span','scene-arrow','⟶'));const sg=node('section','scene-group');const heading=node('div','scene-card-heading');const setup=node('button','scene-setup-button',scene.title);setup.onclick=()=>safe(()=>choose(scene.id));const edit=node('button','scene-edit-button','Edit');edit.setAttribute('aria-label','Edit '+scene.title);edit.onclick=e=>{e.stopPropagation();safe(()=>openOutlineEditor(scene.id))};heading.append(setup,edit);sg.append(heading);const sequences=node('div','scene-sequences');for(const seq of [scene,...children(scene.id).filter(n=>n.kind==='sequence')]){if(!children(seq.id).some(n=>['keyframe','clip'].includes(n.kind)))continue;const group=node('div','sequence-group');const strip=node('div','sequence-strip');children(seq.id).filter(n=>['keyframe','clip'].includes(n.kind)).forEach((n,i)=>{if(i)strip.append(node('span','arrow','→'));const card=node('article','pipeline-card '+n.status+(selected===n.id?' selected':''));card.onclick=()=>safe(()=>choose(n.id));card.append(node('span','card-type',n.kind==='keyframe'?'QWEN / KEYFRAME':'H3 / VIDEO CLIP'),node('h4','',n.title));const prompt=node('textarea');prompt.value=fieldValue(n,'prompt');prompt.disabled=!isEditable(n);prompt.setAttribute('aria-label',n.title+' prompt');prompt.onclick=e=>e.stopPropagation();prompt.oninput=()=>remember(n.id,'prompt',prompt.value);card.append(prompt);const tools=node('div','card-tools');tools.append(node('span','small muted',n.status));if(n.status==='running'){const bar=node('progress');bar.max=100;if(n.progress!==null)bar.value=n.progress;card.append(bar)}for(const [label,command] of [['✦','enhance'],['Save','save'],['↻','redo']]){if(label==='Save'&&!['succeeded','saved'].includes(n.status))continue;if(label==='↻'&&!['succeeded','saved','failed'].includes(n.status))continue;const b=node('button','',label);b.title=command;b.disabled=['queued','running'].includes(n.status)||(command==='enhance'&&!isEditable(n));b.onclick=e=>{e.stopPropagation();safe(async()=>{await commit(n.id);await action(command,n.id)})};tools.append(b)}card.append(tools);strip.append(card)});group.append(strip);sequences.append(group)}sg.append(sequences);root.append(sg)}}
function renderEditor(){const n=current(),valid=n&&shotKinds.includes(n.kind);$('editorTitle').textContent=valid?n.title:assembledEpisodePreview?'Motion-drama pilot preview':'Choose a frame or clip';$('editorType').textContent=valid?(n.kind==='clip'?'MINIMAX H3 / VIDEO':'QWEN / IMAGE'):'SELECT A BOX';$('editorStatus').textContent=(n?.status||'Idle')+(n?.reference_update_note?' · previous reference':'');const editable=valid&&isEditable(n);for(const field of ['prompt','negative','dialogue','sound','seconds']){const e=$(field);if(document.activeElement!==e)e.value=valid?fieldValue(n,field):'';e.disabled=!editable;e.oninput=()=>{if(valid)remember(n.id,field,field==='seconds'?Number(e.value):e.value)}}$('negativeArea').classList.toggle('hidden',!n?.redo_seen);$('clipFields').classList.toggle('hidden',n?.kind!=='clip');$('referenceArea').classList.toggle('hidden',!valid||n.kind==='clip');$('uploadLabel').classList.toggle('hidden',n?.kind!=='reference'||!editable);$('keyframeUploadLabel').classList.toggle('hidden',n?.kind!=='keyframe');$('uploadKeyframe').disabled=!editable;$('keyframeUploadLabel').title=editable?'Use this image directly as the keyframe':'Use Redo first to replace this keyframe; wait for active generation to finish';$('keepPrompt').disabled=!editable;$('localEnhance').disabled=!editable;$('localRun').disabled=!editable;$('saveResult').disabled=!valid||!['succeeded','saved'].includes(n.status);$('redoBox').disabled=!valid||['running','queued'].includes(n.status);$('editorError').textContent=n?.error||'';const references=$('references');references.replaceChildren();if(valid)values().filter(x=>x.kind==='reference'&&!x.archived&&x.id!==n.id).forEach(ref=>{const l=node('label','reference-option'),c=node('input');c.type='checkbox';c.value=ref.id;c.checked=(drafts[n.id]?.references||n.references).includes(ref.id);c.disabled=!editable;c.onchange=()=>{const checked=[...references.querySelectorAll('input:checked')].map(x=>x.value);if(checked.length>30){c.checked=false;toast('Choose up to 30 additional references');return}remember(n.id,'references',checked)};l.append(c);if(ref.output){const img=node('img');img.src=media(ref.output);img.alt=ref.title;img.onclick=e=>{e.preventDefault();e.stopPropagation();openReferenceImage(media(ref.output),ref.title)};l.append(img)}l.append(node('span','',ref.title));references.append(l)});$('publishReference').classList.toggle('hidden',!n?.library_asset||n?.kind!=='reference'||!n?.output);renderPreview();renderShotReferences();if(typeof renderCameraControls==='function')renderCameraControls();$('commandTarget').textContent=valid?'Selected: '+n.title:'Select a prompt box first';for(const [id,field] of [['quickPrompt','prompt'],['quickNegative','negative']]){const e=$(id);if(document.activeElement!==e)e.value=valid?fieldValue(n,field):'';e.disabled=!editable;e.oninput=()=>{if(valid)remember(n.id,field,e.value)}}$('quickNegative').classList.toggle('hidden',!n?.redo_seen);$('quickNegativeLabel').classList.toggle('hidden',!n?.redo_seen)}
function renderLogs(){const root=$('logs');root.replaceChildren();for(const l of project.logs){const line=node('div','log-row '+l.level);line.textContent=new Date(l.time*1000).toLocaleTimeString()+'  '+l.message;root.append(line)}root.scrollTop=root.scrollHeight;const running=values().find(n=>n.status==='running');renderWorkStatus();renderActivityProgress()}
function renderWorkStatus(){if(!project)return;const a=project.activity,running=values().find(n=>n.status==='running');let message;if(a){message=a.task+(a.detail&&a.detail!==a.task?' — '+a.detail:'');if(a.active&&work.length){const elapsed=Math.max(0,Math.floor(Date.now()/1000-a.started));message+=' · '+Math.floor(elapsed/60)+'m '+String(elapsed%60).padStart(2,'0')+'s elapsed'}}else if(running){message='Generating '+(running.kind==='clip'?'video':'image')+': '+running.title+' — '+(running.stage||'Starting')}else if(work.length){message=project.logs.at(-1)?.message||'Waiting to start '+work[0].operation}else message='Ready';$('workStatus').textContent=message;$('workStatus').title=message;renderActivityProgress()}
setInterval(renderWorkStatus,1000);

async function action(command,nid=selected,extra={}){if(command==='runAll'){const scope=nid||episode;for(const id of Object.keys(drafts)){const n=project.nodes[id];if(n&&(withinSelection(id,scope)||n.depends_on===scope))await commit(id)}}const data=await api(base()+'/action','POST',{action:command,node:nid,episode,...extra});if(data.project)accept(data.project);else{toast(command==='runAll'?'Selected work queued. Other scenes will not run.':'Queued '+command);await reload()}return data}
async function saveContext(){const key=contextDraftKey();const n=current();if(n&&!shotKinds.includes(n.kind)){remember(n.id,'text',$('contextText').value);await commit(n.id)}else{const state=await api(base(),'PATCH',{story:$('contextText').value});accept(state)}delete contextDrafts[key]}
async function checkHealth(){const h=await api('/api/health');storyAssetsReady=!!h.story_assets;writtenImportReady=!!h.written_import;if(project)renderProduction();$('services').textContent=(h.ollama?'●':'○')+' Ollama  '+(h.qwen?'●':'○')+' Qwen  '+(h.h3?'●':'○')+' H3';$('services').title='Generator: '+h.generator+' · ComfyUI '+(h.comfyui?'online':'offline')}
$('newProject').onclick=$('startProject').onclick=()=>$('projectDialog').showModal();$('cancelProject').onclick=()=>$('projectDialog').close();$('projectForm').onsubmit=e=>{e.preventDefault();safe(async()=>{const p=await api('/api/projects','POST',{title:$('newTitle').value,story:$('newStory').value,episode_count:$('newEpisodeCount').value?Number($('newEpisodeCount').value):null});$('projectDialog').close();await openProject(p.id)})};$('projectPicker').onchange=()=>safe(()=>openProject($('projectPicker').value));$('storyNode').onclick=()=>safe(()=>choose(null));$('episodePicker').onchange=()=>safe(()=>openEpisode($('episodePicker').value));$('quality').onchange=()=>safe(async()=>accept(await api(base(),'PATCH',{quality:$('quality').value})));$('outlineMode').onclick=()=>setMode('outline');$('pipelineMode').onclick=()=>setMode('pipeline');$('healthRefresh').onclick=()=>safe(checkHealth);$('toggleTree').onclick=()=>{treeOpen.clear();renderTree()};
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>safe(async()=>{if(isLibraryMode())return;if(!projectId)throw Error('Create a project first');await commit();await action(b.dataset.action)}));$('saveContext').onclick=()=>safe(saveContext);$('breakdown').onclick=()=>safe(async()=>{await saveContext();await action('breakdown')});$('enhanceLevel').onclick=()=>safe(async()=>{await saveContext();await action('enhance')});$('enhanceChildren').onclick=()=>safe(async()=>{const ids=children(selected).filter(n=>!n.locked).map(n=>n.id);for(const id of ids)await commit(id);if(!ids.length)throw Error('Generate this level first');await api(base()+'/action','POST',{action:'enhanceAllOutline',node:selected})});
$('keepPrompt').onclick=()=>safe(()=>commit());$('localEnhance').onclick=()=>safe(async()=>{await commit();await action('enhance')});$('localRun').onclick=()=>safe(async()=>{await commit();await action('run')});$('saveResult').onclick=()=>safe(()=>action('save'));$('redoBox').onclick=()=>safe(()=>action('redo'));$('exportEpisode').onclick=()=>safe(async()=>{const clips=values().filter(n=>n.kind==='clip'&&episodeOf(n)===episode);if(!clips.length||clips.some(n=>!n.output||!['succeeded','saved'].includes(n.status)))throw Error('Finish and review every episode clip before saving and assembling.');await action('saveAll',null,{episode});const r=await api(base()+'/export','POST',{episode});assembledEpisodePreview={id:'assembled-'+episode,episode,kind:'clip',output:r.path,version:Date.now(),title:'Complete episode · '+project.nodes[episode].title};renderKey='';renderPreview();toast('Episode saved and assembled. Watch it in the main preview.')});
$('addAsset').onclick=()=>{if(!project)toast('Create a project first');else $('assetDialog').showModal()};$('cancelAsset').onclick=()=>$('assetDialog').close();$('assetForm').onsubmit=e=>{e.preventDefault();safe(async()=>{const state=await api(base()+'/nodes','POST',{kind:$('assetKind').value,title:$('assetName').value,text:$('assetPrompt').value});accept(state);const group=values().filter(n=>n.kind===$('assetKind').value).at(-1);const result=await api(base()+'/nodes','POST',{kind:'reference',parent:group.id,title:$('assetName').value+' / '+$('assetCategory').value,prompt:$('assetPrompt').value,category:$('assetCategory').value});accept(result);const ref=children(group.id).at(-1);$('assetDialog').close();await choose(ref.id)})};$('uploadReference').onchange=()=>safe(async()=>{const file=$('uploadReference').files[0];if(!file)return;const form=new FormData();form.append('file',file);const state=await api(base()+'/references/'+selected+'/upload','POST',form);accept(state);$('uploadReference').value=''});
$('commandToggle').onclick=()=>$('commandPanel').classList.toggle('hidden');$('closeCommand').onclick=()=>$('commandPanel').classList.add('hidden');$('applyQuick').onclick=()=>safe(()=>commit());$('sendCommand').onclick=()=>safe(async()=>{const command=$('commandInput').value.trim();if(!command)return;await commit();const map={'/run':'run','/runall':'runAll','/enhanceall':'enhanceAll','/saveall':'saveAll','/updateall':'refresh'};if(command.startsWith('/')){if(!map[command.toLowerCase()])throw Error('Unknown slash command');await action(map[command.toLowerCase()])}else{if(!selected)throw Error('Select a prompt box first');await action('enhance',selected,{instruction:command})}$('commandInput').value=''});$('commandInput').onkeydown=e=>{if(e.key==='Enter')$('sendCommand').click()};
let libraryState={assets:[]},selectedLibraryAsset=null,libraryLoaded=false;

function treeHeading(label,add,open){const row=node('div','tree-group tree-heading');const plus=node('button','tree-add','+');plus.title='Add '+label.toLowerCase();plus.setAttribute('aria-label','Add '+label.toLowerCase());plus.onclick=add;const title=node('button','tree-heading-label',label);title.onclick=open;row.append(plus,title);return row}
function newLibraryEntry(kind){selectedLibraryAsset=null;setMode(kind==='character'?'characters':kind==='prop'?'props':'locations');safe(async()=>{await loadLibrary();editLibraryAsset(null);$('libraryName').focus()})}
async function openEpisode(id){assembledEpisodePreview=null;await commit();episode=id;selected=null;mode='pipeline';renderKey='';if(!openedEpisodes.includes(id))openedEpisodes.push(id);render()}
function renderEpisodeTabs(){const root=$('episodeTabs');root.replaceChildren();for(const id of openedEpisodes){const ep=project?.nodes[id];if(!ep)continue;const episodes=episodeNodes();const index=episodes.findIndex(n=>n.id===id)+1;const name=ep.title.replace(/^episode\s*\d+\s*[-–—:·]?\s*/i,'').trim().replace(/\s+/g,'_');const tab=node('button',mode==='pipeline'&&episode===id?'active':'','Ep'+index+'-'+name);tab.onclick=()=>safe(()=>openEpisode(id));root.append(tab)}}
function showOutlineDialog(){if(!project)return toast('Create a project first');const options=[new Option('Story → new episode','')];for(const n of values().filter(n=>['arc','episode','scene'].includes(n.kind)))options.push(new Option(n.title+' → new '+({arc:'episode',episode:'scene',scene:'keyframe'}[n.kind]),n.id));$('outlineParent').replaceChildren(...options);const n=current();if(n&&['arc','episode','scene'].includes(n.kind))$('outlineParent').value=n.id;$('outlineTitle').value='';$('outlineText').value='';$('outlineDialog').showModal()}
function openReferenceImage(src,title){const image=$('libraryFullImage');image.src=src;image.alt=title;$('libraryImageTitle').textContent=title;$('libraryImageDialog').showModal()}
function setEpisodeZoom(value){const view=$('preview'),image=view.querySelector('img');if(!image?.naturalWidth)return;const previous=episodeZoom;const centerX=(view.scrollLeft+view.clientWidth/2)/previous,centerY=(view.scrollTop+view.clientHeight/2)/previous;episodeZoom=Math.max(.25,Math.min(4,value));const fit=Math.min(view.clientWidth/image.naturalWidth,view.clientHeight/image.naturalHeight);image.style.width=(image.naturalWidth*fit*episodeZoom)+'px';image.style.height=(image.naturalHeight*fit*episodeZoom)+'px';$('episodeZoomLevel').textContent=Math.round(episodeZoom*100)+'%';$('episodeZoomOut').disabled=episodeZoom<=.25;$('episodeZoomIn').disabled=episodeZoom>=4;view.scrollLeft=centerX*episodeZoom-view.clientWidth/2;view.scrollTop=centerY*episodeZoom-view.clientHeight/2}
function resetEpisodeZoom(){episodeZoom=1;setEpisodeZoom(1);$('preview').scrollLeft=0;$('preview').scrollTop=0}
$('episodeZoomIn').onclick=()=>setEpisodeZoom(episodeZoom*1.25);$('episodeZoomOut').onclick=()=>setEpisodeZoom(episodeZoom/1.25);$('episodeZoomFit').onclick=resetEpisodeZoom;
$('preview').addEventListener('wheel',e=>{if(e.ctrlKey&&$('preview').querySelector('img')){e.preventDefault();setEpisodeZoom(episodeZoom*(e.deltaY<0?1.15:1/1.15))}},{passive:false});
let episodePan=null;$('preview').addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0||!$('preview').querySelector('img'))return;episodePan={x:e.clientX,y:e.clientY,left:$('preview').scrollLeft,top:$('preview').scrollTop};$('preview').setPointerCapture(e.pointerId);e.preventDefault()});$('preview').addEventListener('pointermove',e=>{if(episodePan){$('preview').scrollLeft=episodePan.left+episodePan.x-e.clientX;$('preview').scrollTop=episodePan.top+episodePan.y-e.clientY}});for(const type of ['pointerup','pointercancel','lostpointercapture'])$('preview').addEventListener(type,()=>episodePan=null);window.addEventListener('resize',()=>{if($('preview').querySelector('img'))setEpisodeZoom(episodeZoom)});
$('closeLibraryImage').onclick=()=>$('libraryImageDialog').close();
$('cancelOutline').onclick=()=>$('outlineDialog').close();$('outlineForm').onsubmit=e=>{e.preventDefault();safe(async()=>{const parent=$('outlineParent').value||null;const kind=parent?{arc:'episode',episode:'scene',scene:'keyframe'}[project.nodes[parent].kind]:'episode';const state=await api(base()+'/nodes','POST',{kind,parent,title:$('outlineTitle').value,text:$('outlineText').value});accept(state);$('outlineDialog').close();const created=values().filter(n=>n.kind===kind&&n.parent===parent).at(-1);if(kind==='episode')await openEpisode(created.id);else await choose(created.id)})};

function isLibraryMode(){return mode==='characters'||mode==='locations'||mode==='props'}
function libraryKind(){return mode==='locations'?'location':mode==='props'?'prop':'character'}
function updateModeChrome(){const lib=isLibraryMode();$('backgroundPackDownload').classList.toggle('hidden',mode!=='locations');const tabs=document.querySelector('.ribbon-tabs');if(mode==='pipeline'&&project){$('pipeline').after(tabs)}else{document.querySelector('.ribbon-shell').after(tabs)};$('projectTitle').textContent=project?.title||'No project open';$('workspace').classList.toggle('hidden',!project);document.querySelector('.studio-main').classList.toggle('hidden',lib);$('welcome').classList.toggle('hidden',lib||!!project);$('sharedLibrary').classList.toggle('hidden',!lib);document.querySelectorAll('[data-project-tools]').forEach(e=>e.classList.toggle('hidden',lib));$('libraryRibbon').classList.toggle('hidden',!lib);renderEpisodeTabs();if(project)renderTree();document.querySelectorAll('[data-action],#exportEpisode').forEach(b=>b.disabled=!project);$('addAsset').textContent='＋ New '+libraryKind();if(lib){$('libraryTitle').textContent=mode==='characters'?'Characters':mode==='props'?'Props':'Locations'}sizeWorkspace()}
async function loadLibrary(){libraryState=await api('/api/library');libraryLoaded=true;renderLibraryCards();if(!selectedLibraryAsset||!libraryState.assets.some(a=>a.id===selectedLibraryAsset&&a.kind===libraryKind()))editLibraryAsset(null)}
function libraryImage(path){return '/api/library/media?path='+encodeURIComponent(path)}
function editLibraryAsset(id){selectedLibraryAsset=id;const a=libraryState.assets.find(a=>a.id===id);$('libraryName').value=a?.name||'';$('libraryDescription').value=a?.description||'';const word=libraryKind();$('libraryEditorLabel').textContent=(a?'EDIT ':'NEW ')+word.toUpperCase();$('libraryEditorTitle').textContent=a?'Edit '+a.name:'Create your '+word;$('saveLibraryAsset').textContent='Save '+word;$('libraryVariants').classList.toggle('hidden',!a);$('libraryMessage').textContent='';$('variantForm').reset();$('variantCategory').value=word==='location'?'Angles':'Outfits';renderVariantList(a);renderLibraryCards();if(a)$('libraryForm').scrollIntoView({block:'start',behavior:'smooth'})}
function renderLibraryCards(){const root=$('libraryCards');root.replaceChildren();const query=$('librarySearch').value.toLowerCase();const assets=libraryState.assets.filter(a=>a.kind===libraryKind()&&(a.name+' '+a.description+' '+(a.aliases||[]).join(' ')).toLowerCase().includes(query));if(!assets.length){const empty=node('div','library-empty');empty.append(node('h2','',libraryKind()==='character'?'Your cast starts here.':'Build your reusable locations.'),node('p','',libraryLoaded?'Create a name and save a reference. It will be available in every story.':'Loading your library…'));root.append(empty)}for(const a of assets){const card=node('article','library-card'+(a.id===selectedLibraryAsset?' selected':''));const image=a.variants.find(v=>v.output&&!v.archived);if(image){const img=node('img');img.src=libraryImage(image.output);img.alt=a.name;img.onclick=()=>openReferenceImage(libraryImage(image.output),a.name);card.append(img)}if(a.project_export)card.append(node('p','small muted','Preserved from '+a.project_export.project_title));card.append(node('h3','',a.name),node('p','',a.description),node('p','small muted',a.variants.filter(v=>v.output&&!v.archived).length+' images · '+a.variants.filter(v=>!v.output&&!v.archived).length+' prompts'));const row=node('div','button-row');const edit=node('button','','Edit');edit.onclick=()=>editLibraryAsset(a.id);row.append(edit);const use=node('button','','Use in current project');use.disabled=!project||!a.variants.length;use.onclick=()=>safe(()=>useLibraryAsset(a.id));row.append(use);const target=current();if(project&&target&&target.kind===a.kind&&['character','location'].includes(target.kind)){const assign=node('button','','Use for '+target.title);assign.disabled=!a.variants.some(v=>v.output&&!v.archived)||!!work.length;assign.onclick=()=>safe(async()=>{const result=await api(base()+'/library/'+a.id,'POST',{target_asset:target.id});accept(result.project);toast(a.name+' assigned to '+target.title)});row.append(assign)}card.append(row);root.append(card)}}
function renderVariantList(a){const root=$('variantList');root.replaceChildren();if(!a)return;const planned=node('details','planned-views');planned.append(node('summary','','Planned views · '+a.variants.filter(v=>!v.output&&!v.archived).length+' prompts'));const variants=a.variants.filter(v=>!v.archived||$('showRemovedReferences').checked).sort((x,y)=>Number(!!y.output)-Number(!!x.output));for(const v of variants){const row=node('div','variant-row'+(v.archived?' removed-reference':''));if(v.output){const button=node('button','variant-preview');button.title='View full image';const img=node('img');img.src=libraryImage(v.output);img.alt=v.title;button.append(img);button.onclick=()=>openReferenceImage(libraryImage(v.output),a.name+' / '+v.title);row.append(button)}row.append(node('strong','',v.title),node('span','',v.category+' · '+(v.output?'Image saved · v'+v.version:'Prompt only')));const source=v.provenance;if(source){row.append(node('span','source-type',source.origin==='preserved from deleted project'?'Preserved project reference':source.origin==='downloaded photograph'?'Real photograph'+(source.master?' · master reference':' · alternative setting'):source.origin==='user-provided identity reference'?'User-provided identity reference'+(source.master?' · master':''):source.origin==='user-provided background reference'?'User-provided background reference · original preserved':source.origin==='generated portrait'?(v.output?'Qwen-generated portrait':'Planned Qwen portrait · no image yet'):(v.output?'AI-generated camera view · check geometry':'Planned camera view · no image yet')));if(source.author)row.append(node('span','',source.author));if(source.source_page){const link=node('a','','Source');link.href=source.source_page;link.target='_blank';link.rel='noopener noreferrer';row.append(link)}if(source.license_url){const link=node('a','','License');link.href=source.license_url;link.target='_blank';link.rel='noopener noreferrer';row.append(link)}}if(v.output){const download=node('a','download-view','Download JPG');download.href=libraryImage(v.output);download.download=a.name.replace(/[^a-z0-9]+/gi,'-')+'-'+v.title.replace(/[^a-z0-9]+/gi,'-')+'.jpg';row.append(download)}const use=node('button','','Use in project');use.disabled=!project||!!v.archived;use.onclick=()=>safe(()=>useLibraryAsset(a.id,v.id));row.append(use);const generate=node('button','','Generate in project');generate.disabled=!project||!!v.archived;generate.onclick=()=>safe(()=>useLibraryAsset(a.id,v.id,true));row.append(generate);const remove=node('button',v.archived?'':'warning',v.archived?'Restore':'Remove');remove.onclick=()=>safe(async()=>{await api('/api/library/'+a.id+'/variants/'+v.id+(v.archived?'/restore':'/archive'),'POST',{});await loadLibrary();renderVariantList(libraryState.assets.find(x=>x.id===a.id));toast(v.archived?'Reference restored':'Reference removed. You can restore it from Show removed references.')});row.append(remove);if(v.archived)row.append(node('span','','Removed · original image retained'));if(v.output||v.archived)root.append(row);else planned.append(row)}if(a.variants.some(v=>!v.output&&!v.archived))root.append(planned)}
async function useLibraryAsset(aid,vid=null,generate=false){if(!projectId)throw Error('Open or create a project first');if(!vid&&!libraryState.assets.find(a=>a.id===aid)?.variants.some(v=>v.output))throw Error('Generate or upload a reference image first');const r=await api(base()+'/library/'+aid,'POST',{variants:vid?[vid]:(libraryState.assets.find(a=>a.id===aid)?.variants.filter(v=>v.output&&!v.archived&&v.provenance?.reference_usage!=='alternate-only').map(v=>v.id)||[])});accept(r.project);const ref=r.references[0];if(!ref)throw Error('No reference variant available');mode='pipeline';await choose(ref);if(generate){const n=project.nodes[ref];if(n.locked||n.output){toast('This saved reference is attached. Use Redo to create a new variation.');return}await action('run',ref)}else toast('Reference attached. Select it for your keyframes.')}
