function renderPreview(){const n=previewNode(),output=n?.output||'';const promptOnly=!!n&&!output&&shotKinds.includes(n.kind);const mount=promptOnly?$('promptStage'):$('promptSidebarMount');if($('promptEditor').parentElement!==mount)mount.append($('promptEditor'));$('promptStage').classList.toggle('hidden',!promptOnly);$('preview').classList.toggle('hidden',promptOnly);$('promptSettings').classList.toggle('hidden',!n||(promptOnly&&n.kind!=='clip'&&!n.redo_seen));$('promptSettings').querySelector('summary').textContent=promptOnly?'Dialogue & advanced settings':'Prompt & direction';$('promptStage').setAttribute('aria-label',n?'Prompt for '+n.title:'Generation prompt');const key=output?[projectId,n.id,n.version||0,output].join('|'):'';const view=$('preview');if(renderKey!==key){renderKey=key;view.replaceChildren();if(output){const e=node(n.kind==='clip'?'video':'img');if(n.kind==='clip'){e.controls=true;e.playsInline=true;e.preload='metadata'}else{e.alt=n.title;e.onload=()=>{resetEpisodeZoom();$('previewMeta').textContent=n.title};}e.onerror=()=>{$('previewMeta').textContent='Preview could not load. Click Retry preview.'};e.src=media(output)+'&v='+encodeURIComponent(n.version||0);view.append(e);if(n.kind!=='clip'&&e.complete&&e.naturalWidth)resetEpisodeZoom();}else view.append(node('p','preview-empty',n?.status==='running'?'Generating this take…':'Select a completed keyframe or video to preview it.'));}$('episodeZoomTools').classList.toggle('hidden',!output||n?.kind==='clip');$('previewMeta').textContent=output?(n.id.startsWith('assembled-')?'':n.id===selected?'Current take · ':'Latest keyframe · ')+n.title:'Awaiting generation';$('retryPreview').disabled=!output;}
