function setStorySource(source){storyReferenceSource=source;for(const [id,type] of [['storyGenerateSource','generate'],['storySystemSource','system'],['storyCatalogueSource','catalogue']])$(id).classList.toggle('hidden',type!==source);document.querySelectorAll('[data-story-source]').forEach(b=>b.classList.toggle('active',b.dataset.storySource===source));$('submitStoryReference').textContent=source==='generate'?'Generate reference image':'Add reference image'}
async function addStoryReference(aid,source){if(!storyAssetsReady)return toast('Restart J Director after the current render to activate the three reference choices.');storyReferenceOwner=aid;const a=project.nodes[aid];$('storyReferenceTitle').textContent=a.title+' — reference image';$('storyReferencePrompt').value=a.text;$('storyReferenceFile').value='';$('storyReferenceError').textContent='';setStorySource(source);if(source==='catalogue'){await loadLibrary();const select=$('storyCatalogueReference');select.replaceChildren(new Option('Choose a catalogue image',''));for(const asset of libraryState.assets.filter(x=>x.kind===a.kind))for(const v of asset.variants.filter(v=>v.output&&!v.archived))select.append(new Option(asset.name+' / '+v.title,asset.id+'|'+v.id))}$('storyReferenceDialog').showModal()}
document.querySelectorAll('[data-story-source]').forEach(b=>b.onclick=()=>safe(async()=>{setStorySource(b.dataset.storySource);if(storyReferenceSource==='catalogue'){await loadLibrary();const select=$('storyCatalogueReference');select.replaceChildren(new Option('Choose a catalogue image',''));for(const asset of libraryState.assets.filter(a=>a.kind===project.nodes[storyReferenceOwner].kind))for(const v of asset.variants.filter(v=>v.output&&!v.archived))select.append(new Option(asset.name+' / '+v.title,asset.id+'|'+v.id))}}));
$('cancelStoryReference').onclick=()=>$('storyReferenceDialog').close();$('storyReferenceForm').onsubmit=e=>{e.preventDefault();safe(async()=>{const file=$('storyReferenceFile').files[0];if(storyReferenceSource==='system'&&!file)throw Error('Choose an image from your computer');const chosen=$('storyCatalogueReference').value.split('|');if(storyReferenceSource==='catalogue'&&chosen.length!==2)throw Error('Choose a catalogue image');const result=await api(base()+'/story-assets/'+storyReferenceOwner+'/references','POST',{source:storyReferenceSource,prompt:$('storyReferencePrompt').value,catalogue_asset:chosen[0],catalogue_variant:chosen[1]});accept(result.project);if(storyReferenceSource==='system'){const form=new FormData();form.append('file',file);accept(await api(base()+'/references/'+result.reference+'/upload','POST',form));}$('storyReferenceDialog').close();await reload();toast(storyReferenceSource==='generate'?'Reference image generation queued':'Reference saved inside this story')})};
function renderStoryAssetEditor(){const panel=$('storyAssetPanel');panel.replaceChildren();const a=current(),valid=a&&['character','location'].includes(a.kind);panel.classList.toggle('hidden',!valid);if(!valid)return;panel.append(node('h3','',a.kind==='character'?'Story character':'Story background'),node('p','muted small','Characters are created or imported once; Save a reference to reuse it from the shared catalogue. Backgrounds download a stock master first. Matching extra angles are generated only when needed.'));const used=node('input');used.readOnly=true;used.value=(a.used_in||[]).join(', ')||'Not linked to a scene yet';used.setAttribute('aria-label','Used in');panel.append(node('label','','Used in — episode / scene / keyframe / video'),used);const actions=node('div','button-row');for(const [source,label] of [['generate','Generate from prompt'],['system','Pick from system'],['catalogue','Pick from catalogue']]){const button=node('button','',label);button.onclick=()=>safe(()=>addStoryReference(a.id,source));actions.append(button)}panel.append(actions);if(a.kind==='location'){const findStock=node('button','','Download stock background · Pixabay');findStock.disabled=!!work.length;findStock.onclick=()=>safe(async()=>{toast('Finding a stock background photo…');const result=await api(base()+'/backgrounds/'+a.id+'/stock','POST',{});accept(result.project);toast(result.kept_existing?'Existing master kept. Remove it first if you want a different background.':'Stock photo downloaded and saved to the shared catalogue.')});panel.append(findStock,node('p','muted small','Stock photo first. Keep one master per location; missing matching angles are derived from that master.'))}if(a.catalogue_name)panel.append(node('p','small muted','Shared catalogue character: '+a.catalogue_name));if(a.kind==='character'){const outfit=node('input');outfit.placeholder='Outfit for character sheet (optional; blank keeps the reference outfit)';outfit.setAttribute('aria-label','Character sheet outfit');const forge=node('button','','Create multi-angle sheet · Character Forge');forge.disabled=!!work.length;forge.onclick=()=>safe(async()=>{const result=await api(base()+'/characters/'+a.id+'/sheet','POST',{outfit:outfit.value});accept(result.project,result.jobs);toast('Character sheet queued locally. Each view is a separate render; the master stays unchanged.')});panel.append(outfit,forge,node('p','muted small','Five views: front and side portraits, front/side/rear full body. Review generated views before use. No cloud generation.'));}const grid=node('div','story-reference-grid');for(const ref of children(a.id).filter(n=>n.kind==='reference'&&!n.archived)){const card=node('article','production-character');card.append(node('strong','',ref.title),node('p','muted small',(ref.view_kind?'View: '+ref.view_kind+' · ':'')+ref.status+(ref.requires_review?' · review before use':'')+(a.primary_reference===ref.id?' · primary':'')));if(ref.output){const img=node('img','production-thumb');img.src=media(ref.output)+'&v='+(ref.version||0);img.alt=ref.title;img.onclick=()=>openReferenceImage(media(ref.output),ref.title);card.append(img);const source=ref.source_provenance;if(source?.source_page){const link=node('a','stock-source','Photo source · '+(source.provider||'Stock'));link.href=source.source_page;link.target='_blank';link.rel='noopener noreferrer';card.append(link)}}else card.append(node('p','muted small','Description only — no image yet'));const edit=node('button','','Edit / preview reference');edit.onclick=()=>safe(()=>choose(ref.id));card.append(edit);grid.append(card)}panel.append(grid);const details=node('details');details.append(node('summary','','Requirements by episode / scene'));for(const [id,requirement] of Object.entries(a.requirements||{})){const entry=node('div','story-requirement');entry.append(node('strong','',project.nodes[id]?.title||'Story outline'),node('p','',requirement.text));details.append(entry)}panel.append(details)}
function inheritedStoryLinks(n){const chain=productionChain(n);const result={characters:[],backgrounds:[]};for(const type of ['episode','scene','sequence','keyframe','clip']){const item=chain[type];if(!item)continue;for(const bucket of ['characters','backgrounds'])if(item.asset_links?.[bucket]?.length||item.asset_links_manual)result[bucket]=item.asset_links?.[bucket]||[];}return result}
function renderStoryBindings(n){const main=$('productionSetup'),shot=$('shotSetup');main.replaceChildren();shot.replaceChildren();const isShot=['keyframe','clip'].includes(n.kind);main.classList.toggle('hidden',isShot);shot.classList.toggle('hidden',!isShot);const panel=isShot?shot:main;panel.append(node('h3','','Characters & backgrounds for '+n.title),node('p','muted small','Uses attached references when available. Run All writes prompts and generates missing references, then reuses them. Ollama chooses background views from their angle labels and shot descriptions.'));if(n.background_view_selection){for(const choice of Object.values(n.background_view_selection)){panel.append(node('p','muted small','Background view: '+(project.nodes[choice.reference]?.title||choice.reference)+' — '+choice.reason));}}const links=inheritedStoryLinks(n),disabled=!storyAssetsReady||!isEditable(n)||!!work.length;for(const [bucket,kind,label] of [['characters','character','Characters'],['backgrounds','location','Backgrounds']]){const section=node('div','story-binding-section');section.append(node('strong','',label));for(const asset of values().filter(a=>a.kind===kind&&!a.archived)){const row=node('div','story-binding-row'),checkLabel=node('label','production-check'),check=node('input');check.type='checkbox';check.checked=links[bucket].includes(asset.id);check.disabled=disabled;check.onchange=()=>safe(async()=>{const update=structuredClone(links);update[bucket]=check.checked?[...update[bucket],asset.id]:update[bucket].filter(id=>id!==asset.id);remember(n.id,'asset_links',update);await commit(n.id);renderProduction()});checkLabel.append(check,node('span','',asset.title));const edit=node('button','','Edit / add reference');edit.onclick=()=>safe(()=>choose(asset.id));row.append(checkLabel,edit);section.append(row)}const add=node('button','','＋ Add story '+(kind==='character'?'character':'background'));add.onclick=()=>showStoryAssetDialog(kind);section.append(add);panel.append(section)}}
$('storyRequirements').onclick=()=>safe(async()=>{if(!storyAssetsReady)throw Error('Restart J Director after the active render to load story requirement discovery.');if(current()&&['episode','scene'].includes(current().kind))await saveContext();else await commit();await action('assets',current()&&['episode','scene','keyframe','clip'].includes(current().kind)?selected:null);toast('Updating character and background Markdown requirements; no images will be generated')});

let pendingDeleteProject=null;
async function renderManagedProjects(){const projects=await api('/api/projects');const deleted=await api('/api/deleted-projects');const active=$('managedProjectList');active.replaceChildren();if(!projects.length)active.append(node('p','muted','No active projects.'));for(const p of projects){const row=node('div','managed-project-row');row.append(node('strong','',p.title));const open=node('button','','Open');open.onclick=()=>safe(async()=>{$('manageProjectsDialog').close();await openProject(p.id)});const remove=node('button','warning','Delete');remove.onclick=()=>{pendingDeleteProject=p;$('deleteProjectTitle').textContent='Delete “'+p.title+'”?';$('deleteProjectError').textContent='';$('deleteProjectDialog').showModal()};row.append(open,remove);active.append(row)}const trash=$('deletedProjectList');trash.replaceChildren();if(!deleted.length)trash.append(node('p','muted small','No deleted projects.'));for(const p of deleted){const row=node('div','managed-project-row');row.append(node('span','',p.title));const restore=node('button','','Restore');restore.onclick=()=>safe(async()=>{await api('/api/projects/'+p.id+'/restore','POST',{});await listProjects();await renderManagedProjects();toast('Project restored. Catalogue copies remain available.')});row.append(restore);trash.append(row)}}
$('manageProjects').onclick=()=>safe(async()=>{await renderManagedProjects();$('manageProjectsDialog').showModal()});$('closeManageProjects').onclick=()=>$('manageProjectsDialog').close();$('cancelDeleteProject').onclick=()=>$('deleteProjectDialog').close();
$('confirmDeleteProject').onclick=()=>safe(async()=>{if(!pendingDeleteProject)return;const button=$('confirmDeleteProject');button.disabled=true;$('deleteProjectError').textContent='';try{const result=await api('/api/projects/'+pendingDeleteProject.id,'DELETE');if(projectId===pendingDeleteProject.id){localStorage.removeItem('director-project');await openProject('');}$('deleteProjectDialog').close();pendingDeleteProject=null;libraryLoaded=false;await listProjects();await renderManagedProjects();toast('Project deleted. '+result.preserved_assets+' assets preserved in the catalogue. You can Restore the project.')}catch(error){$('deleteProjectError').textContent=error.message}finally{button.disabled=false}});

$('importWritten').onclick=()=>safe(async()=>{if(!writtenImportReady)throw Error('Restart J Director after the current breakdown to activate written-story import.');await saveContext();await action('importWritten',null);toast('Importing your written structure without generating images or video')});

// Show the selected inputs beside the take; manual overrides stay tucked away.
function renderShotReferences(){
 const root=$('selectedShotReferences'),n=current();root.replaceChildren();const valid=n&&shotKinds.includes(n.kind);root.classList.toggle('hidden',!valid);$('shotReferenceSettings').classList.toggle('hidden',!valid||n.kind==='reference');$('extraReferencesPanel').classList.toggle('hidden',!valid||n.kind==='clip');if(!valid)return;
 root.append(node('h3','','Selected references'));
 const rows=[];const add=(id,role)=>{const ref=project.nodes[id];if(ref&&!ref.archived&&!rows.some(r=>r.ref.id===id))rows.push({ref,role})};
 if(n.kind==='clip'){if(n.depends_on)add(n.depends_on,'Starting keyframe')}
 else if(n.output&&n.render_references?.length){for(const row of n.render_references)add(row.id,row.role)}
 else{
  const links=inheritedStoryLinks(n),chain=productionChain(n),direction=Object.assign({},chain.episode?.production,chain.scene?.production,chain.sequence?.production),shot=productionValue(n);
  let cast=direction.cast||links.characters.map(id=>({character:id,identity:project.nodes[id]?.primary_reference,outfit:project.nodes[id]?.default_outfit}));
  if(Object.values(chain).some(x=>x.asset_links_manual))cast=links.characters.map(id=>({character:id,identity:project.nodes[id]?.primary_reference,outfit:project.nodes[id]?.default_outfit}));
  for(const c of cast){const owner=project.nodes[c.character];if(!owner||owner.offscreen||(shot.characters&&!shot.characters.includes(c.character)))continue;const master=c.identity||children(c.character).find(r=>r.kind==='reference'&&r.output&&!r.archived&&!r.requires_review)?.id;add(master,'Character');if(c.outfit)add(c.outfit,'Outfit');if(shot.expressions?.[c.character])add(shot.expressions[c.character],'Expression');for(const id of c.accessories||[])add(id,'Accessory')}
  if(shot.inherit_background!==false){if(direction.background&&!Object.values(chain).some(x=>x.asset_links_manual))add(direction.background,'Background');else for(const id of links.backgrounds){const owner=project.nodes[id];add(n.background_view_selection?.[id]?.reference||owner?.primary_reference||children(id).find(r=>r.kind==='reference'&&r.output&&!r.archived&&!r.requires_review)?.id,'Background')}}
  for(const id of drafts[n.id]?.references||n.references||[])add(id,'Additional');
 }
 root.append(node('p','muted small',n.kind==='clip'?'Motion starts from this keyframe.':n.output?'References used for this take.':'References are inherited automatically. Ollama chooses a background view when needed.'));
 for(const {ref,role} of rows){const card=node('article','selected-reference-card');if(ref.output){const b=node('button','selected-reference-image');b.title='View '+ref.title;const img=node('img');img.src=media(ref.output)+'&v='+(ref.version||0);img.alt=ref.title;b.append(img);b.onclick=()=>openReferenceImage(media(ref.output),ref.title);card.append(b)}card.append(node('span','small muted',role),node('strong','',ref.title));if(!ref.output)card.append(node('span','small muted','Image will be generated when needed'));root.append(card)}
 if(!rows.length)root.append(node('p','muted small','No image references attached. Your prompt will guide generation.'));
}

let outlineEditTarget=null;
function openOutlineEditor(id){
 const n=project.nodes[id];if(!n||!['episode','scene'].includes(n.kind))return;
 outlineEditTarget=id;$('outlineEditHeading').textContent=n.kind==='episode'?'Edit episode details':'Edit scene details';
 $('outlineEditTitle').value=fieldValue(n,'title');$('outlineEditText').value=contextDrafts[projectId+':'+id]??fieldValue(n,'text');
 $('outlineEditError').textContent='';$('outlineEditBreakdown').textContent=n.kind==='episode'?'Save & break down into scenes':'Save & break down into keyframes';
 $('outlineEditBreakdown').disabled=!!work.length;$('outlineEditDialog').showModal();
}
async function saveOutlineEditor(){
 const n=project.nodes[outlineEditTarget];if(!n)throw Error('Select an episode or scene');
 const state=await api(base()+'/nodes/'+n.id,'PATCH',{title:$('outlineEditTitle').value,text:$('outlineEditText').value});
 delete contextDrafts[projectId+':'+n.id];delete drafts[n.id];accept(state);return n.id;
}
$('cancelOutlineEdit').onclick=()=>$('outlineEditDialog').close();
$('outlineEditForm').onsubmit=e=>{e.preventDefault();safe(async()=>{try{await saveOutlineEditor();$('outlineEditDialog').close();toast('Details saved. The episode workspace stays open.')}catch(error){$('outlineEditError').textContent=error.message}})};
$('outlineEditBreakdown').onclick=()=>safe(async()=>{try{const id=await saveOutlineEditor();const n=project.nodes[id];const existing=n.kind==='episode'&&children(id).some(x=>x.kind==='scene');await action(existing?'rebreakdown':'breakdown',id);$('outlineEditDialog').close();toast('Breakdown queued. Scenes and keyframes will appear in this workspace.')}catch(error){$('outlineEditError').textContent=error.message}});

$('uploadKeyframe').onchange=()=>safe(async()=>{const input=$('uploadKeyframe'),file=input.files[0],target=selected;if(!file)return;try{await commit(target);const form=new FormData();form.append('file',file);const state=await api(base()+'/keyframes/'+target+'/upload','POST',form);accept(state);toast('Your image is now the keyframe. Select its video and Run to animate it.')}finally{input.value=''}});

$('stopAllWork').onclick=()=>safe(async()=>{const button=$('stopAllWork');button.disabled=true;try{const result=await api('/api/work/stop-all','POST',{});toast(result.warnings?.length?result.warnings.join(' '):'Stopped all projects and interrupted rendering. Completed files are kept.')}finally{button.disabled=false}});

function renderActivityProgress(){const bar=$('workProgress'),running=values().find(n=>n.status==='running'),active=work.length>0||!!running;bar.classList.toggle('hidden',!active);bar.setAttribute('aria-busy',String(active));if(!active){bar.removeAttribute('value');bar.removeAttribute('aria-valuetext');return}const percent=Number(running?.progress),known=running&&running.progress!==null&&running.progress!==undefined&&Number.isFinite(percent)&&percent>0;if(known){bar.value=Math.max(0,Math.min(100,percent));bar.setAttribute('aria-valuetext',Math.round(percent)+'% — '+(running.title||'Generating'))}else{bar.removeAttribute('value');bar.setAttribute('aria-valuetext',($('workStatus').textContent||'Working')+' — progress percentage not available yet')}bar.title=bar.getAttribute('aria-valuetext')}
